head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.openMenu = function(menuNm, url, menuCode, scopeId, menuType) {
    // client에서 url 숨기기 메뉴일 경우에는 새 창으로 띄우기 적용 
    if (url == "/") {
        var url = document.location.href + "/";
        window.open(url, "", "width=1200, height=700, left=450, top=100");
    } else {
        menuCode = menuCode || "";
        var layout = "T";
        var tmpUrl;
        var menuCodeParm = menuCode;
        var frameMode; // "wframe", "iframe"
        var favStatus;
        var data;
        //즐겨찾기가 추가 여부 확인하여 flag 붙임.
        favStatus = "T";
        var frameMode = "";
        if (layout == "T") {
            var tabObj = {
                closable: true, //탭 닫기 기능 제공
                openAction: "exist", // exist 는 기존 탭을 갱신, new 는 항상 새로, select는 동일 id 가 존재하면 선택, last: 기존 tab을 마지막 tab으로 이동후 선택
                //							   openAction : "select", // exist 는 기존 탭을 갱신, new 는 항상 새로, select는 동일 id 가 존재하면 선택, last: 기존 tab을 마지막 tab으로 이동후 선택
                label: menuNm
            };
            if (true) {
                frameMode = "wframePreload";
            } else {
                frameMode = "iframe";
            }
            var contObj = {
                frameMode: frameMode,
                scope: true,
                src: url,
                alwaysDraw: false,
                title: menuNm
            };
            var tabComp = $w.getComponentById(scopeId + "_tac_layout");
            tabComp.addTab(menuCode, tabObj, contObj);
            // tabObj의 openAction의 last값의 동작 특이 사항으로 선택이 되지 않은 경우 선택하는 로직 추가
            if (tabComp.getSelectedTabID() !== menuCode) {
                var tabIndex = tabComp.getTabIndex(menuCode);
                if (tabIndex) {
                    tabComp.setSelectedTabIndex(tabIndex);
                }
            }
        } else if (layout == "M") {
            if (true) {
                frameMode = "wframe";
            } else {
                frameMode = "iframe";
            }
            var options = {
                title: menuNm,
                src: url,
                windowTitle: menuNm,
                windowId: menuCode,
                openAction: "existWindow",
                frameMode: frameMode,
                dataObject: {
                    type: "json",
                    name: "param",
                    data: data
                }
            }
            var wdcComp = $w.getComponentById(scopeId + "_wdc_main");
            //var wdcComp = $w.getComponentById("mf_wdc_main");
            wdcComp.createWindow(options);
        }
    }
};
scwin.historyTitle1_onclick = function() {
    scopeId = WebSquare.idCache[this.parentFrame].id;
    scwin.openMenu("mainTab1", "gridView_setColumnVisible_WESD-751_(WSQ-4801)_childTab.xml", "010001", scopeId);
};
scwin.historyTitle2_onclick = function() {
    scopeId = WebSquare.idCache[this.parentFrame].id;
    scwin.openMenu("mainTab2", "gridView_setColumnVisible_WESD-751_(WSQ-4801)_childTab.xml", "010002", scopeId);
};
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById('mf_tac_layout_contents_010001_body_tabControl1_contents_content2_body_gridView1_body_tbody').children[0].style.display != 'none'
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('historyTitle1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "mf_tac_layout_contents_010001_body_tabControl1_tab_tabs1[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "mf_tac_layout_contents_010001_body_tabControl1_tab_tabs1[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tac_layout_contents_010001_body_trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "mf_tac_layout_contents_010001_body_tabControl1_tab_tabs1[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
